<template><main class="admin-content"><NuxtLink to="/admin/accounting" class="text-sm font-bold text-blue-600">← Accounting</NuxtLink><h1 class="mt-2 text-3xl font-black">Suppliers & Purchases</h1><p class="text-slate-500">Purchase orders, supplier bills, GST credits and payments.</p><div v-if="msg" class="my-4 rounded-lg bg-slate-100 p-3">{{msg}}</div><div class="mt-5 grid gap-5 xl:grid-cols-2"><section class="admin-panel p-5"><h2 class="text-xl font-black">Suppliers</h2><div class="mt-3 grid grid-cols-2 gap-2"><input v-model="supplier.name" class="input" placeholder="Supplier name"><input v-model="supplier.contact_name" class="input" placeholder="Contact"><input v-model="supplier.email" class="input" placeholder="Email"><input v-model="supplier.phone" class="input" placeholder="Phone"><input v-model="supplier.abn" class="input" placeholder="ABN"><button class="btn-primary" @click="addSupplier">Add Supplier</button></div><div class="mt-4 divide-y"><div v-for="s in suppliers" :key="s.id" class="py-2"><b>{{s.name}}</b><span class="ml-2 text-xs text-slate-500">{{s.email}}</span></div></div></section><section class="admin-panel p-5"><h2 class="text-xl font-black">New Purchase Order</h2><select v-model.number="po.supplier_id" class="input mt-3"><option :value="0">Choose supplier…</option><option v-for="s in suppliers" :value="s.id">{{s.name}}</option></select><div v-for="(l,n) in po.lines" class="mt-2 grid grid-cols-[1fr_90px_130px_30px] gap-2"><input v-model="l.description" class="input" placeholder="Description"><input v-model.number="l.quantity" class="input" type="number" min="1"><input v-model.number="l.unit_cost_ex_gst" class="input" type="number" step=".01" placeholder="Cost ex GST"><button @click="po.lines.splice(n,1)">×</button></div><div class="mt-3 flex justify-between"><button class="btn-secondary" @click="po.lines.push(line())">+ Line</button><button class="btn-primary" @click="createPO">Create PO</button></div></section></div><section class="admin-panel mt-5 p-5"><h2 class="text-xl font-black">Purchase Orders</h2><div class="mt-3 overflow-x-auto"><table class="w-full text-sm"><thead><tr class="border-b text-left"><th class="p-2">PO</th><th>Supplier</th><th>Date</th><th>Status</th><th class="text-right">GST</th><th class="text-right">Total</th></tr></thead><tbody><tr v-for="x in pos" class="border-b"><td class="p-2 font-bold">{{x.po_number}}</td><td>{{x.accounting_suppliers?.name}}</td><td>{{x.order_date}}</td><td>{{x.status}}</td><td class="text-right">{{money(x.gst_amount)}}</td><td class="text-right">{{money(x.total)}}</td></tr></tbody></table></div></section><section class="admin-panel mt-5 p-5"><h2 class="text-xl font-black">New Supplier Bill</h2><div class="mt-3 grid gap-2 md:grid-cols-3"><select v-model.number="bill.supplier_id" class="input"><option :value="0">Choose supplier…</option><option v-for="s in suppliers" :value="s.id">{{s.name}}</option></select><input v-model="bill.supplier_invoice_number" class="input" placeholder="Supplier invoice #"><input v-model="bill.due_date" class="input" type="date"></div><div v-for="(l,n) in bill.lines" class="mt-2 grid grid-cols-[1fr_90px_130px_30px] gap-2"><input v-model="l.description" class="input" placeholder="Description"><input v-model.number="l.quantity" class="input" type="number" min="1"><input v-model.number="l.unit_cost_ex_gst" class="input" type="number" step=".01" placeholder="Cost ex GST"><button @click="bill.lines.splice(n,1)">×</button></div><div class="mt-3 flex justify-between"><button class="btn-secondary" @click="bill.lines.push(line())">+ Line</button><button class="btn-primary" @click="createBill">Post Supplier Bill</button></div></section><section class="admin-panel mt-5 p-5"><h2 class="text-xl font-black">Supplier Bills / Accounts Payable</h2><div class="mt-3 overflow-x-auto"><table class="w-full text-sm"><thead><tr class="border-b text-left"><th class="p-2">Bill</th><th>Supplier</th><th>Supplier Invoice</th><th>Status</th><th class="text-right">Total</th><th class="text-right">Owing</th><th></th></tr></thead><tbody><tr v-for="b in bills" class="border-b"><td class="p-2 font-bold">{{b.bill_number}}</td><td>{{b.accounting_suppliers?.name}}</td><td>{{b.supplier_invoice_number||'—'}}</td><td>{{b.status}}</td><td class="text-right">{{money(b.total)}}</td><td class="text-right font-bold">{{money(Number(b.total)-Number(b.paid_amount))}}</td><td class="text-right"><button v-if="b.status!=='paid'" class="btn-secondary" @click="pay(b)">Pay</button></td></tr></tbody></table></div></section></main></template><script setup lang="ts">definePageMeta({layout:"admin",middleware:["admin"]});const{adminFetch}=useAdminFetch(),suppliers=ref<any[]>([]),pos=ref<any[]>([]),bills=ref<any[]>([]),msg=ref("");const line=()=>({description:"",quantity:1,unit_cost_ex_gst:0}),supplier=reactive<any>({name:"",contact_name:"",email:"",phone:"",abn:""}),po=reactive<any>({supplier_id:0,lines:[line()]}),bill=reactive<any>({supplier_id:0,supplier_invoice_number:"",due_date:"",lines:[line()]});const money=(v:any)=>new Intl.NumberFormat("en-AU",{style:"currency",currency:"AUD"}).format(Number(v||0));async function load(){[suppliers.value,pos.value,bills.value]=await Promise.all([adminFetch("/api/admin/accounting/suppliers"),adminFetch("/api/admin/accounting/purchase-orders"),adminFetch("/api/admin/accounting/supplier-bills")])}async function addSupplier(){try{await adminFetch("/api/admin/accounting/suppliers",{method:"POST",body:supplier});Object.assign(supplier,{name:"",contact_name:"",email:"",phone:"",abn:""});await load()}catch(e:any){msg.value=e?.data?.statusMessage||e.message}}async function createPO(){try{const x:any=await adminFetch("/api/admin/accounting/purchase-orders",{method:"POST",body:po});msg.value=`${x.po_number} created.`;Object.assign(po,{supplier_id:0,lines:[line()]});await load()}catch(e:any){msg.value=e?.data?.statusMessage||e.message}}async function createBill(){try{const x:any=await adminFetch("/api/admin/accounting/supplier-bills",{method:"POST",body:bill});msg.value=`${x.bill_number} posted to Accounts Payable.`;Object.assign(bill,{supplier_id:0,supplier_invoice_number:"",due_date:"",lines:[line()]});await load()}catch(e:any){msg.value=e?.data?.statusMessage||e.message}}async function pay(b:any){const owing=Number(b.total)-Number(b.paid_amount),raw=prompt(`Payment amount for ${b.bill_number}`,owing.toFixed(2));if(raw===null)return;const ref=prompt("Payment reference","")||"";try{await adminFetch("/api/admin/accounting/supplier-payments",{method:"POST",body:{bill_id:b.id,amount:Number(raw),reference:ref}});msg.value="Supplier payment posted.";await load()}catch(e:any){msg.value=e?.data?.statusMessage||e.message}}onMounted(load)</script><style scoped>.admin-panel{@apply rounded-xl border border-slate-200 bg-white shadow-sm}.input{@apply w-full rounded-lg border border-slate-300 px-3 py-2 text-sm}.btn-primary{@apply rounded-lg bg-blue-600 px-4 py-2 text-sm font-bold text-white}.btn-secondary{@apply rounded-lg border border-slate-300 bg-white px-4 py-2 text-sm font-bold}</style>